import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Container,
    Paper,
    Typography,
    IconButton,
    Box,
    Avatar,
    TextField,
    Button,
    CircularProgress,
    Alert,
    Divider,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogContentText,
    DialogActions
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import EditIcon from '@mui/icons-material/Edit';
import PhotoCameraIcon from '@mui/icons-material/PhotoCamera';
import SaveIcon from '@mui/icons-material/Save';
import CancelIcon from '@mui/icons-material/Cancel';
import DeleteForeverIcon from '@mui/icons-material/DeleteForever';
import { utilisateurService } from '../services/utilisateurService';

const ProfilSettings: React.FC = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);
    
    // Données utilisateur
    const [utilisateur, setUtilisateur] = useState<{
        id: number;
        pseudo: string;
        email: string;
        photo_profil: string | null;
    } | null>(null);
    
    // Mode édition
    const [isEditingPseudo, setIsEditingPseudo] = useState(false);
    const [newPseudo, setNewPseudo] = useState('');
    const [selectedPhoto, setSelectedPhoto] = useState<File | null>(null);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    
    // Suppression de compte
    const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
    const [deleteConfirmText, setDeleteConfirmText] = useState('');
    
    // Mot de passe
    const [showPasswordForm, setShowPasswordForm] = useState(false);
    const [passwordData, setPasswordData] = useState({
        nouveauMotDePasse: '',
        confirmationMotDePasse: ''
    });

    // Charger l'utilisateur depuis sessionStorage (pas d'appel API)
    useEffect(() => {
        const storedUser = sessionStorage.getItem('utilisateur');
        if (!storedUser) {
            navigate('/login');
            return;
        }
        const user = JSON.parse(storedUser);
        setUtilisateur(user);
        setNewPseudo(user.pseudo);
    }, [navigate]);

    // Gérer le changement de photo
    const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setSelectedPhoto(file);
            const reader = new FileReader();
            reader.onloadend = () => {
                setPhotoPreview(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    // Modifier le pseudo
    const handleUpdatePseudo = async () => {
        if (!newPseudo.trim() || !utilisateur) return;
        
        setLoading(true);
        setError(null);
        
        try {
            await utilisateurService.modifierUtilisateur(utilisateur.id, { pseudo: newPseudo });
            
            // Mis à jour sessionStorage
            const updatedUser = { ...utilisateur, pseudo: newPseudo };
            sessionStorage.setItem('utilisateur', JSON.stringify(updatedUser));
            setUtilisateur(updatedUser);
            
            setSuccess("Pseudo modifié avec succès");
            setIsEditingPseudo(false);
        } catch (err: any) {
            setError(err.response?.data?.error || "Erreur lors de la modification du pseudo");
        } finally {
            setLoading(false);
            setTimeout(() => setSuccess(null), 3000);
        }
    };

    // Modifier la photo de profil
    const handleUpdatePhoto = async () => {
        if (!selectedPhoto || !utilisateur) return;
        
        setLoading(true);
        setError(null);
        
        const formData = new FormData();
        formData.append('photo_profil', selectedPhoto);
        
        try {
            // Modification pdp
            const response = await utilisateurService.modifierPhotoProfil(utilisateur.id, formData);
            
            // Mis à jour sessionStorage
            const updatedUser = { ...utilisateur, photo_profil: selectedPhoto.name };
            sessionStorage.setItem('utilisateur', JSON.stringify(updatedUser));
            setUtilisateur(updatedUser);
            setPhotoPreview(null);
            setSelectedPhoto(null);
            
            setSuccess("Photo de profil modifiée avec succès");
        } catch (err: any) {
            setError(err.response?.data?.error || "Erreur lors de la modification de la photo");
        } finally {
            setLoading(false);
            setTimeout(() => setSuccess(null), 3000);
        }
    };

    // Modification mot de passe
    const handleUpdatePassword = async () => {
        if (!utilisateur) return;
        
        if (passwordData.nouveauMotDePasse !== passwordData.confirmationMotDePasse) {
            setError("Les mots de passe ne correspondent pas");
            return;
        }
        
        if (passwordData.nouveauMotDePasse.length < 6) {
            setError("Le mot de passe doit contenir au moins 6 caractères");
            return;
        }
        
        setLoading(true);
        setError(null);
        
        try {
            await utilisateurService.modifierMotDePasse(
                utilisateur.email,
                passwordData.nouveauMotDePasse,
                passwordData.confirmationMotDePasse
            );
            
            setSuccess("Mot de passe modifié avec succès");
            setShowPasswordForm(false);
            setPasswordData({ nouveauMotDePasse: '', confirmationMotDePasse: '' });
        } catch (err: any) {
            setError(err.response?.data?.error || "Erreur lors de la modification du mot de passe");
        } finally {
            setLoading(false);
            setTimeout(() => setSuccess(null), 3000);
        }
    };

    // Suppression du compte
    const handleDeleteAccount = async () => {
        if (!utilisateur) return;
        
        setLoading(true);
        try {
            await utilisateurService.supprimerUtilisateur(utilisateur.id);
            sessionStorage.clear();
            navigate('/login');
        } catch (err: any) {
            setError(err.response?.data?.error || "Erreur lors de la suppression du compte");
            setOpenDeleteDialog(false);
        } finally {
            setLoading(false);
        }
    };

    if (!utilisateur) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
                <CircularProgress sx={{ color: '#773399' }} />
            </Box>
        );
    }

    const avatarUrl = utilisateur.photo_profil
        ? `http://localhost:8080/uploads/${utilisateur.photo_profil}`
        : '/icons/green.jpg';

    return (
        <Container maxWidth="md" sx={{ py: 4 }}>
            <Paper sx={{ p: 3 }}>
                {/* En-tête */}
                <Box display="flex" alignItems="center" mb={3}>
                    <IconButton onClick={() => navigate('/profil')} sx={{ mr: 2 }}>
                        <ArrowBackIcon />
                    </IconButton>
                    <Typography variant="h5" sx={{ fontFamily: 'Poppins', fontWeight: 600 }}>
                        Paramètres du profil
                    </Typography>
                </Box>

                {error && (
                    <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
                        {error}
                    </Alert>
                )}
                
                {success && (
                    <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>
                        {success}
                    </Alert>
                )}

                {/* Section Photo de profil */}
                <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 4 }}>
                    <Box sx={{ position: 'relative' }}>
                        <Avatar
                            src={photoPreview || avatarUrl}
                            sx={{ width: 120, height: 120, border: '3px solid #773399' }}
                        />
                        <label htmlFor="photo-upload">
                            <input
                                id="photo-upload"
                                type="file"
                                accept="image/*"
                                onChange={handlePhotoChange}
                                style={{ display: 'none' }}
                            />
                            <IconButton
                                component="span"
                                sx={{
                                    position: 'absolute',
                                    bottom: 0,
                                    right: 0,
                                    backgroundColor: '#773399',
                                    color: 'white',
                                    '&:hover': { backgroundColor: '#5a2a7a' }
                                }}
                            >
                                <PhotoCameraIcon />
                            </IconButton>
                        </label>
                    </Box>
                    {selectedPhoto && (
                        <Button
                            onClick={handleUpdatePhoto}
                            disabled={loading}
                            variant="contained"
                            size="small"
                            sx={{ mt: 2, borderRadius: 45, backgroundColor: '#773399' }}
                        >
                            {loading ? <CircularProgress size={20} /> : 'Enregistrer la photo'}
                        </Button>
                    )}
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Section Pseudo */}
                <Box sx={{ mb: 3 }}>
                    <Typography variant="subtitle1" sx={{ fontFamily: 'Poppins', fontWeight: 600, mb: 1 }}>
                        Pseudo
                    </Typography>
                    {isEditingPseudo ? (
                        <Box display="flex" gap={1}>
                            <TextField
                                fullWidth
                                size="small"
                                value={newPseudo}
                                onChange={(e) => setNewPseudo(e.target.value)}
                                sx={{
                                    '& .MuiOutlinedInput-root': {
                                        '&.Mui-focused fieldset': { borderColor: '#773399' }
                                    }
                                }}
                            />
                            <IconButton onClick={handleUpdatePseudo} disabled={loading} sx={{ color: '#4caf50' }}>
                                <SaveIcon />
                            </IconButton>
                            <IconButton onClick={() => setIsEditingPseudo(false)} sx={{ color: '#f44336' }}>
                                <CancelIcon />
                            </IconButton>
                        </Box>
                    ) : (
                        <Box display="flex" alignItems="center" gap={2}>
                            <Typography variant="body1">@{utilisateur.pseudo}</Typography>
                            <IconButton onClick={() => setIsEditingPseudo(true)} size="small" sx={{ color: '#773399' }}>
                                <EditIcon fontSize="small" />
                            </IconButton>
                        </Box>
                    )}
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Section Email */}
                <Box sx={{ mb: 3 }}>
                    <Typography variant="subtitle1" sx={{ fontFamily: 'Poppins', fontWeight: 600, mb: 1 }}>
                        Email
                    </Typography>
                    <Typography variant="body1">{utilisateur.email}</Typography>
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Section Mot de passe */}
                <Box sx={{ mb: 3 }}>
                    <Typography variant="subtitle1" sx={{ fontFamily: 'Poppins', fontWeight: 600, mb: 1 }}>
                        Mot de passe
                    </Typography>
                    {showPasswordForm ? (
                        <Box>
                            <TextField
                                fullWidth
                                type="password"
                                label="Nouveau mot de passe"
                                size="small"
                                value={passwordData.nouveauMotDePasse}
                                onChange={(e) => setPasswordData({ ...passwordData, nouveauMotDePasse: e.target.value })}
                                sx={{ mb: 2 }}
                            />
                            <TextField
                                fullWidth
                                type="password"
                                label="Confirmation"
                                size="small"
                                value={passwordData.confirmationMotDePasse}
                                onChange={(e) => setPasswordData({ ...passwordData, confirmationMotDePasse: e.target.value })}
                                sx={{ mb: 2 }}
                            />
                            <Box display="flex" gap={1}>
                                <Button
                                    variant="contained"
                                    onClick={handleUpdatePassword}
                                    disabled={loading}
                                    sx={{ borderRadius: 45, backgroundColor: '#773399' }}
                                >
                                    {loading ? <CircularProgress size={20} /> : 'Enregistrer'}
                                </Button>
                                <Button
                                    variant="outlined"
                                    onClick={() => {
                                        setShowPasswordForm(false);
                                        setPasswordData({ nouveauMotDePasse: '', confirmationMotDePasse: '' });
                                    }}
                                    sx={{ borderRadius: 45, borderColor: '#773399', color: '#773399' }}
                                >
                                    Annuler
                                </Button>
                            </Box>
                        </Box>
                    ) : (
                        <Button
                            variant="outlined"
                            onClick={() => setShowPasswordForm(true)}
                            sx={{ borderRadius: 45, borderColor: '#773399', color: '#773399' }}
                        >
                            Changer le mot de passe
                        </Button>
                    )}
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Section Suppression du compte */}
                <Box>
                    <Typography variant="subtitle1" sx={{ fontFamily: 'Poppins', fontWeight: 600, color: '#f44336', mb: 1 }}>
                        Zone dangereuse
                    </Typography>
                    <Button
                        variant="outlined"
                        startIcon={<DeleteForeverIcon />}
                        onClick={() => setOpenDeleteDialog(true)}
                        sx={{ borderRadius: 45, borderColor: '#f44336', color: '#f44336' }}
                    >
                        Supprimer mon compte
                    </Button>
                </Box>
            </Paper>

            {/* Dialogue de confirmation de suppression */}
            <Dialog open={openDeleteDialog} onClose={() => setOpenDeleteDialog(false)}>
                <DialogTitle>Supprimer définitivement le compte ?</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        Cette action est irréversible. Toutes vos publications et commentaires seront supprimés.
                        <br /><br />
                        Tapez <strong>{utilisateur.pseudo}</strong> pour confirmer :
                    </DialogContentText>
                    <TextField
                        fullWidth
                        size="small"
                        value={deleteConfirmText}
                        onChange={(e) => setDeleteConfirmText(e.target.value)}
                        sx={{ mt: 2 }}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpenDeleteDialog(false)}>Annuler</Button>
                    <Button
                        onClick={handleDeleteAccount}
                        disabled={deleteConfirmText !== utilisateur.pseudo}
                        color="error"
                        variant="contained"
                    >
                        Supprimer
                    </Button>
                </DialogActions>
            </Dialog>
        </Container>
    );
};

export default ProfilSettings;
